interface FormGroupProps {
  label?: string;
  error?: string;
  hint?: string;
  required?: boolean;
  children: ReactNode;
  style?: React.CSSProperties;
}

export function FormGroup({
  label,
  error,
  hint,
  required,
  children,
  style,
}: FormGroupProps) {
  return (
    <div style={{ marginBottom: '20px', ...style }}>
