}

// ============================================================================
// Text Input
// ============================================================================

export interface InputProps extends InputHTMLAttributes<HTMLInputElement> {
  error?: boolean;
  icon?: ReactNode;
  iconPosition?: 'left' | 'right';
}

export const Input = forwardRef<HTMLInputElement, InputProps>(
  function Input(
    { error, icon, iconPosition = 'left', style, onFocus, onBlur, ...props },
    ref
  ) {
    const [isFocused, setIsFocused] = React.useState(false);

    const handleFocus = (e: React.FocusEvent<HTMLInputElement>) => {
      setIsFocused(true);
      onFocus?.(e);
    };

    const handleBlur = (e: React.FocusEvent<HTMLInputElement>) => {
      setIsFocused(false);
      onBlur?.(e);
    };

    const combinedStyles: React.CSSProperties = {
      ...baseInputStyles,
      ...(isFocused ? focusStyles : {}),
      ...(error ? errorStyles : {}),
      ...(icon ? { paddingLeft: iconPosition === 'left' ? '44px' : '16px' } : {}),
      ...(icon ? { paddingRight: iconPosition === 'right' ? '44px' : '16px' } : {}),
      ...style,
    };

    if (icon) {
      return (
        <div style={{ position: 'relative' }}>
          <span
            style={{
              position: 'absolute',
              top: '50%',
              transform: 'translateY(-50%)',
              [iconPosition]: '14px',
              display: 'flex',
              alignItems: 'center',
              color: APPLE_COLORS.text.tertiary,
              pointerEvents: 'none',
            }}
          >
            {icon}
          </span>
          <input
            ref={ref}
            style={combinedStyles}
            onFocus={handleFocus}
            onBlur={handleBlur}
            {...props}
          />
        </div>
      );
    }

    return (
      <input
        ref={ref}
        style={combinedStyles}
        onFocus={handleFocus}
        onBlur={handleBlur}
        {...props}
      />
    );
  }
);

