// ============================================================================
// Range Slider
// ============================================================================

export interface SliderProps extends Omit<InputHTMLAttributes<HTMLInputElement>, 'type'> {
  label?: string;
  showValue?: boolean;
  valueFormatter?: (value: number) => string;
  trackColor?: string;
  thumbColor?: string;
}

export const Slider = forwardRef<HTMLInputElement, SliderProps>(
  function Slider(
    {
      label,
      showValue = true,
      valueFormatter = (v) => String(v),
      trackColor = APPLE_COLORS.primary,
      thumbColor = '#FFFFFF',
      value,
      min = 0,
      max = 100,
      style,
      ...props
    },
    ref
  ) {
    const currentValue = typeof value === 'number' ? value : Number(value) || 0;
    const percentage = ((currentValue - Number(min)) / (Number(max) - Number(min))) * 100;

    const trackStyle: React.CSSProperties = {
      width: '100%',
      height: '6px',
      borderRadius: '3px',
      background: `linear-gradient(to right, ${trackColor} ${percentage}%, ${APPLE_COLORS.gray[200]} ${percentage}%)`,
      outline: 'none',
      appearance: 'none',
      cursor: 'pointer',
    };

    return (
      <div style={{ width: '100%', ...style }}>
        {(label || showValue) && (
          <div
            style={{
              display: 'flex',
              justifyContent: 'space-between',
              marginBottom: '8px',
            }}
          >
            {label && <span style={labelStyles}>{label}</span>}
            {showValue && (
              <span
                style={{
                  fontSize: '14px',
                  fontWeight: 600,
                  color: trackColor,
                }}
              >
                {valueFormatter(currentValue)}
              </span>
            )}
          </div>
        )}
        <input
          ref={ref}
          type="range"
          value={value}
          min={min}
          max={max}
          style={trackStyle}
          {...props}
        />
        <style>
          {`
            input[type="range"]::-webkit-slider-thumb {
              -webkit-appearance: none;
              appearance: none;
              width: 22px;
              height: 22px;
              border-radius: 50%;
              background: ${thumbColor};
              cursor: pointer;
              border: none;
              box-shadow: 0 2px 8px rgba(0,0,0,0.2);
              transition: transform 0.2s ease;
            }
            input[type="range"]::-webkit-slider-thumb:hover {
              transform: scale(1.1);
            }
            input[type="range"]::-webkit-slider-thumb:active {
              transform: scale(0.95);
            }
            input[type="range"]::-moz-range-thumb {
              width: 22px;
              height: 22px;
              border-radius: 50%;
              background: ${thumbColor};
              cursor: pointer;
              border: none;
              box-shadow: 0 2px 8px rgba(0,0,0,0.2);
            }
          `}
        </style>
      </div>
    );
  }
);

export default Input;

/**
 * Eisenhower Matrix Task Management System
 * Modal Component
 * 
 * Apple 风格模态框组件，支持动画和多种尺寸
 */

import React, {
  useEffect,
  useCallback,
  useRef,
  type ReactNode,
  type CSSProperties,
} from 'react';
import { createPortal } from 'react-dom';
import { ANIMATION_CONFIG, APPLE_COLORS, Z_INDEX } from '../../constants';

// ============================================================================
// Types
// ============================================================================

export type ModalSize = 'sm' | 'md' | 'lg' | 'xl' | 'full';

export interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title?: string;
  subtitle?: string;
  size?: ModalSize;
  closeOnOverlayClick?: boolean;
  closeOnEscape?: boolean;
  showCloseButton?: boolean;
  children: ReactNode;
  footer?: ReactNode;
  style?: CSSProperties;
}

// ============================================================================
// Size Configurations
// ============================================================================

const sizeStyles: Record<ModalSize, CSSProperties> = {
  sm: { maxWidth: '360px' },
  md: { maxWidth: '480px' },
  lg: { maxWidth: '640px' },
  xl: { maxWidth: '800px' },
  full: { maxWidth: '95vw', maxHeight: '95vh' },
};

// ============================================================================
// Close Icon
// ============================================================================

function CloseIcon() {
  return (
    <svg width="20" height="20" viewBox="0 0 20 20" fill="none">
      <path
        d="M15 5L5 15M5 5L15 15"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
      />
    </svg>
  );
}

// ============================================================================
// Modal Component
// ============================================================================

export function Modal({
  isOpen,
  onClose,
  title,
  subtitle,
  size = 'md',
  closeOnOverlayClick = true,
  closeOnEscape = true,
  showCloseButton = true,
  children,
  footer,
  style,
}: ModalProps) {
  const modalRef = useRef<HTMLDivElement>(null);
  const [isAnimating, setIsAnimating] = React.useState(false);
  const [shouldRender, setShouldRender] = React.useState(false);

  // Handle open/close animations
  useEffect(() => {
    if (isOpen) {
      setShouldRender(true);
      requestAnimationFrame(() => setIsAnimating(true));
    } else {
      setIsAnimating(false);
      const timer = setTimeout(() => setShouldRender(false), ANIMATION_CONFIG.duration.normal);
      return () => clearTimeout(timer);
    }
  }, [isOpen]);

  // Handle escape key
  useEffect(() => {
    if (!closeOnEscape || !isOpen) return;

    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onClose();
      }
    };

    document.addEventListener('keydown', handleEscape);
    return () => document.removeEventListener('keydown', handleEscape);
  }, [closeOnEscape, isOpen, onClose]);

  // Lock body scroll
  useEffect(() => {
    if (isOpen) {
      const originalOverflow = document.body.style.overflow;
      document.body.style.overflow = 'hidden';
      return () => {
        document.body.style.overflow = originalOverflow;
      };
    }
  }, [isOpen]);

  // Focus trap
  useEffect(() => {
    if (!isOpen || !modalRef.current) return;

    const modal = modalRef.current;
    const focusableElements = modal.querySelectorAll<HTMLElement>(
      'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
    );

    const firstElement = focusableElements[0];
    const lastElement = focusableElements[focusableElements.length - 1];

    firstElement?.focus();

    const handleTab = (e: KeyboardEvent) => {
      if (e.key !== 'Tab') return;

      if (e.shiftKey) {
        if (document.activeElement === firstElement) {
          e.preventDefault();
          lastElement?.focus();
        }
      } else {
        if (document.activeElement === lastElement) {
          e.preventDefault();
          firstElement?.focus();
        }
      }
    };

    document.addEventListener('keydown', handleTab);
    return () => document.removeEventListener('keydown', handleTab);
  }, [isOpen]);

  const handleOverlayClick = useCallback(
    (e: React.MouseEvent) => {
      if (closeOnOverlayClick && e.target === e.currentTarget) {
        onClose();
      }
    },
    [closeOnOverlayClick, onClose]
  );

  if (!shouldRender) return null;

  const overlayStyles: CSSProperties = {
    position: 'fixed',
    inset: 0,
    backgroundColor: 'rgba(0, 0, 0, 0.4)',
    backdropFilter: 'blur(4px)',
    WebkitBackdropFilter: 'blur(4px)',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    padding: '20px',
    zIndex: Z_INDEX.modal,
    opacity: isAnimating ? 1 : 0,
    transition: `opacity ${ANIMATION_CONFIG.duration.normal}ms ${ANIMATION_CONFIG.easing.smooth}`,
  };

  const contentStyles: CSSProperties = {
    backgroundColor: '#FFFFFF',
    borderRadius: '20px',
    boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.25)',
    width: '100%',
    maxHeight: '85vh',
    display: 'flex',
    flexDirection: 'column',
    transform: isAnimating ? 'scale(1) translateY(0)' : 'scale(0.95) translateY(10px)',
    opacity: isAnimating ? 1 : 0,
    transition: `all ${ANIMATION_CONFIG.duration.normal}ms ${ANIMATION_CONFIG.easing.spring}`,
    ...sizeStyles[size],
    ...style,
  };

  const headerStyles: CSSProperties = {
    padding: '24px 24px 0',
    position: 'relative',
  };

  const titleStyles: CSSProperties = {
    fontSize: '20px',
    fontWeight: 700,
    color: APPLE_COLORS.text.primary,
    margin: 0,
    paddingRight: showCloseButton ? '36px' : 0,
  };

  const subtitleStyles: CSSProperties = {
    fontSize: '14px',
    color: APPLE_COLORS.text.secondary,
    marginTop: '4px',
  };

  const closeButtonStyles: CSSProperties = {
    position: 'absolute',
    top: '20px',
    right: '20px',
    width: '32px',
    height: '32px',
    borderRadius: '50%',
    border: 'none',
    backgroundColor: APPLE_COLORS.gray[100],
    color: APPLE_COLORS.text.secondary,
    cursor: 'pointer',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    transition: `all ${ANIMATION_CONFIG.duration.fast}ms ease`,
  };

  const bodyStyles: CSSProperties = {
    padding: '20px 24px',
    overflowY: 'auto',
    flex: 1,
  };

  const footerStyles: CSSProperties = {
    padding: '16px 24px 24px',
    display: 'flex',
    justifyContent: 'flex-end',
    gap: '12px',
    borderTop: `1px solid ${APPLE_COLORS.gray[200]}`,
  };

  const modalContent = (
    <div style={overlayStyles} onClick={handleOverlayClick} role="dialog" aria-modal="true">
      <div ref={modalRef} style={contentStyles} onClick={(e) => e.stopPropagation()}>
        {(title || showCloseButton) && (
          <div style={headerStyles}>
            {title && (
              <div>
                <h2 style={titleStyles}>{title}</h2>
                {subtitle && <p style={subtitleStyles}>{subtitle}</p>}
              </div>
            )}
            {showCloseButton && (
              <button
                style={closeButtonStyles}
                onClick={onClose}
                aria-label="关闭"
                onMouseEnter={(e) => {
                  e.currentTarget.style.backgroundColor = APPLE_COLORS.gray[200];
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.backgroundColor = APPLE_COLORS.gray[100];
                }}
              >
                <CloseIcon />
              </button>
            )}
          </div>
        )}

        <div style={bodyStyles}>{children}</div>

        {footer && <div style={footerStyles}>{footer}</div>}
      </div>
    </div>
  );

  return createPortal(modalContent, document.body);
}

// ============================================================================
// Confirm Dialog
// ============================================================================

export interface ConfirmDialogProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: () => void;
  title: string;
  message: string;
  confirmText?: string;
  cancelText?: string;
  variant?: 'danger' | 'warning' | 'info';
  loading?: boolean;
}

export function ConfirmDialog({
  isOpen,
  onClose,
  onConfirm,
  title,
  message,
  confirmText = '确认',
  cancelText = '取消',
  variant = 'danger',
  loading = false,
}: ConfirmDialogProps) {
  const variantColors = {
    danger: APPLE_COLORS.error,
    warning: APPLE_COLORS.warning,
    info: APPLE_COLORS.primary,
  };

  const confirmButtonStyle: CSSProperties = {
    padding: '10px 20px',
    fontSize: '15px',
    fontWeight: 600,
    border: 'none',
    borderRadius: '10px',
    cursor: loading ? 'not-allowed' : 'pointer',
    backgroundColor: variantColors[variant],
    color: '#FFFFFF',
    opacity: loading ? 0.7 : 1,
    transition: `all ${ANIMATION_CONFIG.duration.fast}ms ease`,
  };

  const cancelButtonStyle: CSSProperties = {
    padding: '10px 20px',
    fontSize: '15px',
    fontWeight: 600,
    border: 'none',
    borderRadius: '10px',
    cursor: 'pointer',
    backgroundColor: APPLE_COLORS.gray[100],
    color: APPLE_COLORS.text.primary,
    transition: `all ${ANIMATION_CONFIG.duration.fast}ms ease`,
  };

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      size="sm"
      showCloseButton={false}
    >
      <div style={{ textAlign: 'center', padding: '10px 0 20px' }}>
        <h3
          style={{
            fontSize: '18px',
            fontWeight: 700,
            color: APPLE_COLORS.text.primary,
            marginBottom: '12px',
          }}
        >
          {title}
        </h3>
        <p
          style={{
            fontSize: '15px',
            color: APPLE_COLORS.text.secondary,
            lineHeight: 1.5,
          }}
        >
          {message}
        </p>
      </div>
      <div
        style={{
          display: 'flex',
          gap: '12px',
          justifyContent: 'center',
          paddingTop: '10px',
        }}
      >
        <button
          style={cancelButtonStyle}
          onClick={onClose}
          disabled={loading}
        >
          {cancelText}
        </button>
        <button
          style={confirmButtonStyle}
          onClick={onConfirm}
          disabled={loading}
        >
          {loading ? '处理中...' : confirmText}
        </button>
      </div>
    </Modal>
  );
}

export default Modal;

/**
 * Eisenhower Matrix Task Management System
 * Card Component
 * 
 * Apple 风格卡片组件，支持玻璃效果和多种变体
 */

import React, { type ReactNode, type CSSProperties } from 'react';
import { ANIMATION_CONFIG, APPLE_COLORS } from '../../constants';
import { getGlassStyle } from '../../utils/colors';

// ============================================================================
// Types
// ============================================================================

export type CardVariant = 'default' | 'elevated' | 'glass' | 'outlined';
export type CardPadding = 'none' | 'sm' | 'md' | 'lg';

export interface CardProps {
  variant?: CardVariant;
  padding?: CardPadding;
  hoverable?: boolean;
  clickable?: boolean;
  selected?: boolean;
  children: ReactNode;
  header?: ReactNode;
  footer?: ReactNode;
  style?: CSSProperties;
  className?: string;
  onClick?: () => void;
}

// ============================================================================
// Style Configurations
// ============================================================================

const paddingStyles: Record<CardPadding, string> = {
  none: '0',
  sm: '12px',
  md: '20px',
  lg: '28px',
};

const getVariantStyles = (variant: CardVariant): CSSProperties => {
  switch (variant) {
    case 'elevated':
      return {
        backgroundColor: '#FFFFFF',
        boxShadow: '0 4px 20px rgba(0, 0, 0, 0.08)',
      };
    case 'glass':
      return getGlassStyle('light', 20);
    case 'outlined':
      return {
        backgroundColor: '#FFFFFF',
        border: `1px solid ${APPLE_COLORS.gray[200]}`,
      };
    default:
      return {
        backgroundColor: '#FFFFFF',
        boxShadow: '0 1px 3px rgba(0, 0, 0, 0.04)',
      };
  }
};

// ============================================================================
// Card Component
// ============================================================================

export function Card({
  variant = 'default',
  padding = 'md',
  hoverable = false,
  clickable = false,
  selected = false,
  children,
  header,
  footer,
  style,
  onClick,
}: CardProps) {
  const [isHovered, setIsHovered] = React.useState(false);

  const baseStyles: CSSProperties = {
    borderRadius: '16px',
    overflow: 'hidden',
    transition: `all ${ANIMATION_CONFIG.duration.normal}ms ${ANIMATION_CONFIG.easing.smooth}`,
    cursor: clickable ? 'pointer' : 'default',
    ...getVariantStyles(variant),
  };

  const hoverStyles: CSSProperties = hoverable && isHovered
    ? {
        transform: 'translateY(-2px)',
        boxShadow: '0 8px 30px rgba(0, 0, 0, 0.12)',
      }
    : {};

  const selectedStyles: CSSProperties = selected
    ? {
        borderColor: APPLE_COLORS.primary,
        boxShadow: `0 0 0 2px ${APPLE_COLORS.primary}`,
      }
    : {};

  const combinedStyles: CSSProperties = {
    ...baseStyles,
    ...hoverStyles,
    ...selectedStyles,
    ...style,
  };

  const handleMouseEnter = () => {
    if (hoverable) setIsHovered(true);
  };

  const handleMouseLeave = () => {
    if (hoverable) setIsHovered(false);
  };

  return (
    <div
      style={combinedStyles}
      onClick={onClick}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      role={clickable ? 'button' : undefined}
      tabIndex={clickable ? 0 : undefined}
    >
      {header && (
        <div
          style={{
            padding: paddingStyles[padding],
            paddingBottom: '0',
            borderBottom: `1px solid ${APPLE_COLORS.gray[100]}`,
          }}
        >
          {header}
        </div>
      )}

      <div style={{ padding: paddingStyles[padding] }}>
        {children}
      </div>

      {footer && (
        <div
          style={{
            padding: paddingStyles[padding],
            paddingTop: '0',
            borderTop: `1px solid ${APPLE_COLORS.gray[100]}`,
          }}
        >
          {footer}
        </div>
      )}
    </div>
  );
}

// ============================================================================
// Stat Card (for statistics display)
// ============================================================================

export interface StatCardProps {
  label: string;
  value: string | number;
  icon?: ReactNode;
  trend?: {
    value: number;
    isPositive: boolean;
  };
  color?: string;
  style?: CSSProperties;
}

export function StatCard({
  label,
  value,
  icon,
  trend,
  color = APPLE_COLORS.primary,
  style,
}: StatCardProps) {
  return (
    <Card variant="default" padding="md" style={style}>
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between' }}>
        <div>
          <p
            style={{
              fontSize: '14px',
              color: APPLE_COLORS.text.secondary,
              marginBottom: '8px',
            }}
          >
            {label}
          </p>
          <p
            style={{
              fontSize: '32px',
              fontWeight: 700,
              color: color,
              lineHeight: 1,
            }}
          >
            {value}
          </p>
          {trend && (
            <div
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: '4px',
                marginTop: '8px',
                fontSize: '13px',
                color: trend.isPositive ? APPLE_COLORS.success : APPLE_COLORS.error,
              }}
            >
              <span>{trend.isPositive ? '↑' : '↓'}</span>
              <span>{Math.abs(trend.value)}%</span>
            </div>
          )}
        </div>
        {icon && (
          <div
            style={{
              width: '44px',
              height: '44px',
              borderRadius: '12px',
              backgroundColor: `${color}15`,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              color: color,
            }}
          >
            {icon}
          </div>
        )}
      </div>
    </Card>
  );
}

// ============================================================================
// Profile Card
// ============================================================================

export interface ProfileCardProps {
  avatar?: string | ReactNode;
  name: string;
  subtitle?: string;
  actions?: ReactNode;
  style?: CSSProperties;
}

export function ProfileCard({
  avatar,
  name,
  subtitle,
  actions,
  style,
}: ProfileCardProps) {
  const renderAvatar = () => {
    if (typeof avatar === 'string') {
      return (
        <img
          src={avatar}
          alt={name}
          style={{
            width: '64px',
            height: '64px',
            borderRadius: '50%',
            objectFit: 'cover',
          }}
        />
      );
    }

    if (avatar) {
      return avatar;
    }

    // Default avatar with initials
    return (
      <div
        style={{
          width: '64px',
          height: '64px',
          borderRadius: '50%',
          background: `linear-gradient(135deg, ${APPLE_COLORS.primary}, ${APPLE_COLORS.secondary})`,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          color: '#FFFFFF',
          fontSize: '24px',
          fontWeight: 700,
        }}
      >
        {name.charAt(0).toUpperCase()}
      </div>
    );
  };

  return (
    <Card variant="elevated" padding="lg" style={style}>
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: '16px',
        }}
      >
        {renderAvatar()}
        <div style={{ flex: 1 }}>
          <h3
            style={{
              fontSize: '18px',
              fontWeight: 700,
              color: APPLE_COLORS.text.primary,
              marginBottom: '4px',
            }}
          >
            {name}
          </h3>
          {subtitle && (
            <p
              style={{
                fontSize: '14px',
                color: APPLE_COLORS.text.secondary,
              }}
            >
              {subtitle}
            </p>
          )}
        </div>
        {actions && <div>{actions}</div>}
      </div>
    </Card>
  );
}

// ============================================================================
// Section Card (for grouped content)
// ============================================================================

export interface SectionCardProps {
  title: string;
  icon?: ReactNode;
  actions?: ReactNode;
  children: ReactNode;
  collapsible?: boolean;
  defaultCollapsed?: boolean;
  style?: CSSProperties;
}

export function SectionCard({
  title,
  icon,
  actions,
  children,
  collapsible = false,
  defaultCollapsed = false,
  style,
}: SectionCardProps) {
  const [isCollapsed, setIsCollapsed] = React.useState(defaultCollapsed);

  const headerContent = (
    <div
      style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        padding: '16px 20px',
        cursor: collapsible ? 'pointer' : 'default',
      }}
      onClick={() => collapsible && setIsCollapsed(!isCollapsed)}
    >
      <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
        {icon && (
          <span style={{ color: APPLE_COLORS.primary, display: 'flex' }}>
            {icon}
          </span>
        )}
        <h3
          style={{
            fontSize: '17px',
            fontWeight: 600,
            color: APPLE_COLORS.text.primary,
            margin: 0,
          }}
        >
          {title}
        </h3>
      </div>
      <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
        {actions}
        {collapsible && (
          <span
            style={{
              transform: isCollapsed ? 'rotate(0deg)' : 'rotate(180deg)',
              transition: `transform ${ANIMATION_CONFIG.duration.fast}ms ease`,
              color: APPLE_COLORS.text.tertiary,
            }}
          >
            ▼
          </span>
        )}
      </div>
    </div>
  );

  return (
    <Card variant="elevated" padding="none" style={style}>
      {headerContent}
      {!isCollapsed && (
        <div
          style={{
            padding: '0 20px 20px',
            borderTop: `1px solid ${APPLE_COLORS.gray[100]}`,
          }}
        >
          <div style={{ paddingTop: '16px' }}>{children}</div>
        </div>
      )}
    </Card>
  );
}

export default Card;

