 * Eisenhower Matrix Task Management System
 * Coordinate Utilities
 * 
 * 矩阵坐标与像素位置之间的转换计算
 */

import type {
  MatrixCoordinate,
  PixelPosition,
  MatrixDimensions,
  ImportanceLevel,
  UrgencyIndex,
  Quadrant,
} from '../types';
import { MATRIX_CONFIG } from '../constants';

// ============================================================================
// Matrix Dimension Calculations
// ============================================================================

/**
 * 计算矩阵单元格尺寸
 */
export function calculateMatrixDimensions(
  containerWidth: number,
  containerHeight: number
): MatrixDimensions {
  const cellWidth = containerWidth / (MATRIX_CONFIG.URGENCY_LEVELS - 1);
  const cellHeight = containerHeight / (MATRIX_CONFIG.IMPORTANCE_LEVELS - 1);

  return {
    width: containerWidth,
    height: containerHeight,
    cellWidth,
    cellHeight,
  };
}

// ============================================================================
// Coordinate to Position Conversions
// ============================================================================

/**
 * 将矩阵坐标转换为像素位置
 * 
 * 坐标系说明：
 * - urgency: 0 (左侧，1年) → 12 (右侧，15分钟)
 * - importance: 1 (底部，1星) → 7 (顶部，7星)
 * 
 * 像素系说明：
 * - x: 0 (左) → width (右)
 * - y: 0 (上) → height (下)
 */
export function coordinateToPosition(
  coordinate: MatrixCoordinate,
  dimensions: MatrixDimensions
): PixelPosition {
  const { urgency, importance } = coordinate;
  const { width, height, cellWidth, cellHeight } = dimensions;

  // X轴：urgency 直接映射到 x 位置
  // urgency 0 → x = halfCell
  // urgency 12 → x = width - halfCell
  const halfCellWidth = cellWidth / 2;
  const x = halfCellWidth + urgency * cellWidth;

  // Y轴：importance 需要反转（高重要度在顶部）
  // importance 7 → y = halfCell (顶部)
  // importance 1 → y = height - halfCell (底部)
  const halfCellHeight = cellHeight / 2;
  const y = halfCellHeight + (MATRIX_CONFIG.IMPORTANCE_LEVELS - importance) * cellHeight;

  return { x, y };
}

/**
 * 将像素位置转换为矩阵坐标
 */
export function positionToCoordinate(
  position: PixelPosition,
  dimensions: MatrixDimensions
): MatrixCoordinate {
  const { x, y } = position;
  const { cellWidth, cellHeight } = dimensions;

  const halfCellWidth = cellWidth / 2;
  const halfCellHeight = cellHeight / 2;

  // 计算 urgency：减去半个单元格后除以单元格宽度
  const adjustedX = x - halfCellWidth;
  let urgency = Math.round(adjustedX / cellWidth);

  // 计算 importance：Y轴反转
  const adjustedY = y - halfCellHeight;
  let importance = MATRIX_CONFIG.IMPORTANCE_LEVELS - Math.round(adjustedY / cellHeight);

  // 边界限制
  urgency = clampUrgency(urgency);
  importance = clampImportance(importance);

  return { urgency, importance };
}

/**
 * 将百分比位置转换为矩阵坐标
 */
export function percentToCoordinate(
  percentX: number,
  percentY: number
): MatrixCoordinate {
  // percentX: 0% (左) → 100% (右)
  // percentY: 0% (上) → 100% (下)

  let urgency = Math.round((percentX / 100) * (MATRIX_CONFIG.URGENCY_LEVELS - 1));
  let importance = MATRIX_CONFIG.IMPORTANCE_LEVELS - 
    Math.round((percentY / 100) * (MATRIX_CONFIG.IMPORTANCE_LEVELS - 1));

  urgency = clampUrgency(urgency);
  importance = clampImportance(importance);

  return { urgency, importance };
}

/**
 * 将矩阵坐标转换为百分比位置
 */
export function coordinateToPercent(
  coordinate: MatrixCoordinate
): { percentX: number; percentY: number } {
  const { urgency, importance } = coordinate;

  const percentX = (urgency / (MATRIX_CONFIG.URGENCY_LEVELS - 1)) * 100;
  const percentY = ((MATRIX_CONFIG.IMPORTANCE_LEVELS - importance) / 
    (MATRIX_CONFIG.IMPORTANCE_LEVELS - 1)) * 100;

  return { percentX, percentY };
}

// ============================================================================
// Quadrant Determination
// ============================================================================

/**
 * 根据坐标判断所属象限
 */
export function getQuadrant(coordinate: MatrixCoordinate): Quadrant {
  const { urgency, importance } = coordinate;

  // 中心线：urgency = 6, importance = 4
  const isUrgent = urgency >= 6;
  const isImportant = importance >= 4;

  if (isImportant && isUrgent) {
    return 'important-urgent';
  } else if (isImportant && !isUrgent) {
    return 'important-not-urgent';
  } else if (!isImportant && isUrgent) {
    return 'not-important-urgent';
  } else {
    return 'not-important-not-urgent';
  }
}

/**
 * 获取象限中心坐标
 */
export function getQuadrantCenter(quadrant: Quadrant): MatrixCoordinate {
  const quadrantCenters: Record<Quadrant, MatrixCoordinate> = {
    'important-not-urgent': { urgency: 3 as UrgencyIndex, importance: 5 as ImportanceLevel },
    'important-urgent': { urgency: 9 as UrgencyIndex, importance: 5 as ImportanceLevel },
    'not-important-not-urgent': { urgency: 3 as UrgencyIndex, importance: 2 as ImportanceLevel },
    'not-important-urgent': { urgency: 9 as UrgencyIndex, importance: 2 as ImportanceLevel },
  };

  return quadrantCenters[quadrant];
}

// ============================================================================
// Boundary Clamping
// ============================================================================

/**
 * 限制 urgency 值在有效范围内
 */
export function clampUrgency(value: number): UrgencyIndex {
  return Math.max(0, Math.min(12, Math.round(value))) as UrgencyIndex;
}

/**
 * 限制 importance 值在有效范围内
 */
export function clampImportance(value: number): ImportanceLevel {
  return Math.max(1, Math.min(7, Math.round(value))) as ImportanceLevel;
}

/**
 * 限制像素位置在矩阵边界内
 */
export function clampPosition(
  position: PixelPosition,
  dimensions: MatrixDimensions
): PixelPosition {
  return {
    x: Math.max(0, Math.min(dimensions.width, position.x)),
    y: Math.max(0, Math.min(dimensions.height, position.y)),
  };
}

// ============================================================================
// Distance Calculations
// ============================================================================

/**
 * 计算两个像素位置之间的距离
 */
export function calculateDistance(
  positionA: PixelPosition,
  positionB: PixelPosition
): number {
  const dx = positionB.x - positionA.x;
  const dy = positionB.y - positionA.y;
  return Math.sqrt(dx * dx + dy * dy);
}

/**
 * 计算两个坐标之间的曼哈顿距离
 */
export function calculateManhattanDistance(
  coordA: MatrixCoordinate,
  coordB: MatrixCoordinate
): number {
  return Math.abs(coordB.urgency - coordA.urgency) + 
         Math.abs(coordB.importance - coordA.importance);
}

/**
 * 判断点击是否在任务节点范围内
 */
export function isPointInNode(
  point: PixelPosition,
  nodeCenter: PixelPosition,
  nodeRadius: number = MATRIX_CONFIG.NODE_SIZE / 2
): boolean {
  return calculateDistance(point, nodeCenter) <= nodeRadius;
}

// ============================================================================
// Grid Line Positions
// ============================================================================

/**
 * 生成垂直网格线位置（百分比）
 */
export function generateVerticalGridLines(): number[] {
  const lines: number[] = [];
  for (let i = 0; i <= MATRIX_CONFIG.URGENCY_LEVELS - 1; i++) {
    lines.push((i / (MATRIX_CONFIG.URGENCY_LEVELS - 1)) * 100);
  }
  return lines;
}

/**
 * 生成水平网格线位置（百分比）
 */
export function generateHorizontalGridLines(): number[] {
  const lines: number[] = [];
  for (let i = 0; i <= MATRIX_CONFIG.IMPORTANCE_LEVELS - 1; i++) {
    lines.push((i / (MATRIX_CONFIG.IMPORTANCE_LEVELS - 1)) * 100);
  }
  return lines;
}

/**
 * 获取坐标轴中心位置（百分比）
 */
export function getAxisCenterPercent(): { centerX: number; centerY: number } {
  // 中心线位置：urgency=6 对应 X 轴中心，importance=4 对应 Y 轴中心
  const centerX = (6 / (MATRIX_CONFIG.URGENCY_LEVELS - 1)) * 100;
  const centerY = ((MATRIX_CONFIG.IMPORTANCE_LEVELS - 4) / 
    (MATRIX_CONFIG.IMPORTANCE_LEVELS - 1)) * 100;

  return { centerX, centerY };
}

// ============================================================================
// Snap to Grid
// ============================================================================

/**
 * 将位置吸附到最近的网格交叉点
 */
export function snapToGrid(
  position: PixelPosition,
  dimensions: MatrixDimensions,
  enabled: boolean = true
): PixelPosition {
  if (!enabled) return position;

  const coordinate = positionToCoordinate(position, dimensions);
  return coordinateToPosition(coordinate, dimensions);
}

// ============================================================================
// Label Positioning
// ============================================================================

/**
 * 计算紧急程度标签位置
 */
export function getUrgencyLabelPosition(
  urgencyIndex: UrgencyIndex,
  dimensions: MatrixDimensions
): PixelPosition {
  const coordinate: MatrixCoordinate = { 
    urgency: urgencyIndex, 
    importance: 1 as ImportanceLevel 
  };
  const position = coordinateToPosition(coordinate, dimensions);

  return {
    x: position.x,
    y: dimensions.height + 8, // 标签在矩阵下方
  };
}

/**
 * 计算重要程度标签位置
 */
export function getImportanceLabelPosition(
  importanceLevel: ImportanceLevel,
  dimensions: MatrixDimensions
): PixelPosition {
  const coordinate: MatrixCoordinate = { 
    urgency: 0 as UrgencyIndex, 
    importance: importanceLevel 
  };
  const position = coordinateToPosition(coordinate, dimensions);

  return {
    x: -8, // 标签在矩阵左侧
    y: position.y,
  };
}
