    12	/**
    13	 * 格式化日期为中文友好格式
    14	 */
    15	export function formatDate(dateString: string): string {
    16	  const date = new Date(dateString);
    17	  const now = new Date();
    18	  
    19	  // 计算日期差异
    20	  const diffMs = now.getTime() - date.getTime();
    21	  const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));
    22	  const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
    23	  const diffMinutes = Math.floor(diffMs / (1000 * 60));
    24	  
    25	  // 相对时间显示
    26	  if (diffMinutes < 1) {
    27	    return '刚刚';
    28	  }
    29	  
    30	  if (diffMinutes < 60) {
    31	    return `${diffMinutes}分钟前`;
    32	  }
    33	  
    34	  if (diffHours < 24) {
    35	    return `${diffHours}小时前`;
    36	  }
    37	  
    38	  // 今天
    39	  if (isToday(date)) {
    40	    return `今天 ${formatTime(date)}`;
    41	  }
    42	  
    43	  // 昨天
    44	  if (isYesterday(date)) {
    45	    return `昨天 ${formatTime(date)}`;
    46	  }
    47	  
    48	  // 前天
    49	  if (diffDays === 2) {
    50	    return `前天 ${formatTime(date)}`;
    51	  }
    52	  
    53	  // 一周内
    54	  if (diffDays < 7) {
    55	    return `${diffDays}天前`;
    56	  }
    57	  
    58	  // 同年
    59	  if (date.getFullYear() === now.getFullYear()) {
    60	    return `${date.getMonth() + 1}月${date.getDate()}日 ${formatTime(date)}`;
    61	  }
    62	  
    63	  // 不同年
    64	  return `${date.getFullYear()}年${date.getMonth() + 1}月${date.getDate()}日`;
    65	}
