   212	export function formatTimeAgo(timestamp: string | number | Date): string {
   213	  const date = new Date(timestamp);
   214	  const now = new Date();
   215	  const diffMs = now.getTime() - date.getTime();
   216	  
   217	  const seconds = Math.floor(diffMs / 1000);
   218	  const minutes = Math.floor(seconds / 60);
