   220	  const days = Math.floor(hours / 24);
   221	  const weeks = Math.floor(days / 7);
   222	  const months = Math.floor(days / 30);
   223	  const years = Math.floor(days / 365);
   224	  
   225	  if (seconds < 60) return '刚刚';
   226	  if (minutes < 60) return `${minutes}分钟前`;
   227	  if (hours < 24) return `${hours}小时前`;
   228	  if (days < 7) return `${days}天前`;
   229	  if (weeks < 4) return `${weeks}周前`;
   230	  if (months < 12) return `${months}个月前`;
