   300	/** 紧急程度对应的分钟数 */
   301	const URGENCY_MINUTES: Record<number, number> = {
   302	  0: 365 * 24 * 60,    // 1年
   303	  1: 182 * 24 * 60,    // 半年
   304	  2: 90 * 24 * 60,     // 3个月
   305	  3: 30 * 24 * 60,     // 1个月
   306	  4: 7 * 24 * 60,      // 1周
   307	  5: 3 * 24 * 60,      // 3天
   308	  6: 24 * 60,          // 1天
   309	  7: 10 * 60,          // 10小时
   310	  8: 4 * 60,           // 4小时
   311	  9: 2 * 60,           // 2小时
   312	  10: 60,              // 1小时
