   325	/**
   326	 * 根据截止时间推算紧急程度
   327	 */
   328	export function getUrgencyFromDeadline(deadline: Date): number {
   329	  const now = new Date();
   330	  const diffMinutes = (deadline.getTime() - now.getTime()) / (1000 * 60);
   331	  
   332	  // 找到最接近的紧急程度
   333	  const entries = Object.entries(URGENCY_MINUTES);
   334	  for (let i = entries.length - 1; i >= 0; i--) {
   335	    if (diffMinutes <= Number(entries[i][1])) {
   336	      return Number(entries[i][0]);
   337	    }
   338	  }
   339	  
   340	  return 0; // 默认最不紧急
   341	}
