export function getUrgencyFromDeadline(deadline: Date): number {
  const now = new Date();
  const diffMinutes = (deadline.getTime() - now.getTime()) / (1000 * 60);

  // 找到最接近的紧急程度
  const entries = Object.entries(URGENCY_MINUTES);
  for (let i = entries.length - 1; i >= 0; i--) {
    const entry = entries[i];
    if (entry && diffMinutes <= Number(entry[1])) {
      return Number(entry[0]);
    }
  }

  return 0; // 默认最不紧急
}

