export function calculateStreak(completionDates: string[]): number {
  if (completionDates.length === 0) return 0;

  // 按日期排序并去重
  const uniqueDates = [...new Set(
    completionDates.map(d => formatForDatePicker(new Date(d)))
  )].sort().reverse();

  const today = formatForDatePicker(new Date());
  const yesterday = formatForDatePicker(addDays(new Date(), -1));

  // 如果今天或昨天没有记录，则连续天数为0
  const firstDate = uniqueDates[0];
  if (!firstDate || (firstDate !== today && firstDate !== yesterday)) {
    return 0;
  }

  let streak = 1;
  for (let i = 1; i < uniqueDates.length; i++) {
    const currentDateStr = uniqueDates[i - 1];
    const prevDateStr = uniqueDates[i];

    if (!currentDateStr || !prevDateStr) break;

    const currentDate = new Date(currentDateStr);
    const prevDate = new Date(prevDateStr);

    if (daysBetween(currentDate, prevDate) === 1) {
      streak++;
    } else {
      break;
    }
  }

  return streak;
}

