// ============================================================================
// Task-specific Color Generation
// ============================================================================

const DEFAULT_COLOR = '#007AFF';

/**
 * 获取任务节点颜色
 * 基于重要程度的基础色，紧急程度影响透明度
 */
export function getTaskNodeColor(
  importance: ImportanceLevel,
  urgency: UrgencyIndex
): string {
  const baseColor = IMPORTANCE_COLORS[importance - 1] ?? DEFAULT_COLOR;

  // 紧急程度影响透明度：0 (不紧急) → 0.4, 12 (最紧急) → 1.0
  const minOpacity = 0.4;
  const maxOpacity = 1.0;
  const opacity = minOpacity + (urgency / 12) * (maxOpacity - minOpacity);

  return withAlpha(baseColor, opacity);
}

/**
 * 获取任务节点悬停颜色
 */
export function getTaskNodeHoverColor(
  importance: ImportanceLevel,
  urgency: UrgencyIndex
): string {
  const baseColor = IMPORTANCE_COLORS[importance - 1] ?? DEFAULT_COLOR;
  const brighterColor = adjustBrightness(baseColor, 10);

  // 悬停时增加透明度
  const opacity = Math.min(1, 0.6 + (urgency / 12) * 0.4);

  return withAlpha(brighterColor, opacity);
}

/**
 * 获取任务节点边框颜色
 */
export function getTaskNodeBorderColor(
  importance: ImportanceLevel,
  isSelected: boolean = false
): string {
  if (isSelected) {
    return APPLE_COLORS.primary;
  }

  const baseColor = IMPORTANCE_COLORS[importance - 1] ?? DEFAULT_COLOR;
  return adjustBrightness(baseColor, -20);
}

/**
 * 获取任务节点阴影
 */
export function getTaskNodeShadow(
  importance: ImportanceLevel,
  _urgency: UrgencyIndex,
  isHovered: boolean = false
): string {
  const baseColor = IMPORTANCE_COLORS[importance - 1] ?? DEFAULT_COLOR;
  const shadowColor = withAlpha(baseColor, isHovered ? 0.4 : 0.2);
  const blur = isHovered ? 15 : 8;
  const spread = isHovered ? 2 : 0;

  return `0 4px ${blur}px ${spread}px ${shadowColor}`;
}

