   321	/**
   322	 * 从任务列表生成时间线数据
   323	 */
   324	export function generateTimelineFromTasks(
   325	  tasks: Task[],
   326	  type: 'created' | 'completed' | 'all' = 'all'
   327	): TimelineItemData[] {
   328	  const items: TimelineItemData[] = [];
   329	
   330	  tasks.forEach(task => {
   331	    if (type === 'created' || type === 'all') {
   332	      items.push({
   333	        id: `${task.id}-created`,
   334	        type: 'created',
   335	        task,
   336	        timestamp: task.createdAt,
   337	      });
   338	    }
   339	
   340	    if ((type === 'completed' || type === 'all') && task.completed && task.completedAt) {
   341	      items.push({
   342	        id: `${task.id}-completed`,
   343	        type: 'completed',
   344	        task,
   345	        timestamp: task.completedAt,
   346	      });
   347	    }
   348	  });
   349	
   350	  // 按时间倒序排列
   351	  return items.sort((a, b) => 
   352	    new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
   353	  );
   354	}
   355	
   356	export default Timeline;
   357

