  const errors: FormErrors = {};

  if (!data.username.trim()) {
    errors.username = '请输入用户名';
  } else if (data.username.length < 2) {
    errors.username = '用户名至少需要 2 个字符';
  } else if (data.username.length > 20) {
    errors.username = '用户名不能超过 20 个字符';
  }

  if (!data.password) {
    errors.password = '请输入密码';
  } else if (data.password.length < VALIDATION.password.minLength) {
    errors.password = `密码至少需要 ${VALIDATION.password.minLength} 个字符`;
  }

  return errors;
}

